<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Update\MessageUpdateUsecase;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageUidVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTargetVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageUrgentVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageContentVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageRetriesVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Update\MessageUpdateParams;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Update\MessageUpdateResult;

class MessageUpdateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly MessageUpdateUsecase $updateUsecase,
    ) {
    }
    #[OA\Put(
        path: "/api/template/template/{uid}",
        tags: ["Message"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/MessageApiDTO")),
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/MessageApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
        new OA\Response(response: 409, description: "Optimist lock"),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function update(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Update Message");
        $span = $this->startSpan("Update Message");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $value = $this->readMessage($request);
            $result = $this->updateUsecase->update($uid, $value);
            $this->sql->commit();
            $value = $this->mapMessage($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readMessage(ServerRequestInterface $request): MessageUpdateParams
    {
        $this->logDebug("Read entity for Message");
        $span = $this->startSpan("Read entity for Message");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new MessageUpdateParams();
            $valueUid = MessageUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            $valueTarget = MessageTargetVO::tryFrom($body['target'] ?? null, $errorsList);
            if (null !== $valueTarget) {
                $value->target($valueTarget);
            }
            if (in_array('tenant', array_keys($body))) {
                $value->tenant(MessageTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList));
            }
            $valueUrgent = MessageUrgentVO::tryFrom($body['urgent'] ?? null, $errorsList);
            if (null !== $valueUrgent) {
                $value->urgent($valueUrgent);
            }
            $valueContent = MessageContentVO::tryFrom($body['content'] ?? null, $errorsList);
            if (null !== $valueContent) {
                $value->content($valueContent);
            }
            $valueRetries = MessageRetriesVO::tryFrom($body['retries'] ?? null, $errorsList);
            if (null !== $valueRetries) {
                $value->retries($valueRetries);
            }
            $value->version(MessageVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapMessage(ServerRequestInterface $request, MessageUpdateResult $value): MessageApiDTO
    {
        $this->logDebug("Map entity to output dto for Message");
        $span = $this->startSpan("Map entity to output dto for Message");
        try {
            $tenant = $value->getTenant();
            $dto = new MessageApiDTO();
            $dto->uid = $value->getUid();
            $dto->target = $value->getTarget();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->urgent = $value->isUrgent();
            $dto->content = $value->getContent();
            $dto->retries = $value->getRetries();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->sendAt = $value->getSendAt()?->format(DateTime::ATOM);
            $dto->lockAt = $value->getLockAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
